// ============ GENERAL SETTING ================

//remove bootstrap active border

textarea:hover,
textarea:active,
textarea:focus,
button:focus,
button:active,
button:hover,
label:focus,
.btn:active,
.btn.active,
input[type="submit"]:active,
input[type="submit"]:focus,
input[type="submit"]:hover,
input[type="date"]:active,
input[type="date"]:focus,
input[type="button"]:active,
input[type="button"]:focus,
input[type="text"]:active,
input[type="text"]:focus {
  outline: 0px !important;
  -webkit-appearance: none;
  box-shadow: none;
}

.body {
  color: #0e9f9c !important;
}

// ================= Loader ================

#loading-animation {
  z-index: 100;
  position: absolute;
  min-height: 4000px;
  width: 100%;
  background: $dark-blue;
  @include media-breakpoint-down(md) {
    display: none;
  }
}

#loader {
  z-index: 100;
  height: 175px;
  left: 0;
  margin: auto;
  position: absolute;
  right: 0;
  top: 6%;
  width: 175px;
}
#loader .dot {
  bottom: 0;
  height: 100%;
  left: 0;
  margin: auto;
  position: absolute;
  right: 0;
  top: 0;
  width: 87.5px;
}
#loader .dot::before {
  border-radius: 100%;
  content: "";
  height: 87.5px;
  left: 0;
  position: absolute;
  right: 0;
  top: 0;
  transform: scale(0);
  width: 87.5px;
}
#loader .dot:nth-child(7n + 1) {
  transform: rotate(45deg);
}
#loader .dot:nth-child(7n + 1)::before {
  animation: 0.8s linear 0.1s normal none infinite running load;
  background: $gradient-1 none repeat scroll 0 0;
}
#loader .dot:nth-child(7n + 2) {
  transform: rotate(90deg);
}
#loader .dot:nth-child(7n + 2)::before {
  animation: 0.8s linear 0.2s normal none infinite running load;
  background: $gradient-3 none repeat scroll 0 0;
}
#loader .dot:nth-child(7n + 3) {
  transform: rotate(135deg);
}
#loader .dot:nth-child(7n + 3)::before {
  animation: 0.8s linear 0.3s normal none infinite running load;
  background: $gradient-4 none repeat scroll 0 0;
}
#loader .dot:nth-child(7n + 4) {
  transform: rotate(180deg);
}
#loader .dot:nth-child(7n + 4)::before {
  animation: 0.8s linear 0.4s normal none infinite running load;
  background: $gradient-5 none repeat scroll 0 0;
}
#loader .dot:nth-child(7n + 5) {
  transform: rotate(225deg);
}
#loader .dot:nth-child(7n + 5)::before {
  animation: 0.8s linear 0.5s normal none infinite running load;
  background: $gradient-7 none repeat scroll 0 0;
}
#loader .dot:nth-child(7n + 6) {
  transform: rotate(270deg);
}
#loader .dot:nth-child(7n + 6)::before {
  animation: 0.8s linear 0.6s normal none infinite running load;
  background: $gradient-8 none repeat scroll 0 0;
}
#loader .dot:nth-child(7n + 7) {
  transform: rotate(315deg);
}
#loader .dot:nth-child(7n + 7)::before {
  animation: 0.8s linear 0.7s normal none infinite running load;
  background: $gradient-9 none repeat scroll 0 0;
}
#loader .dot:nth-child(7n + 8) {
  transform: rotate(360deg);
}
#loader .dot:nth-child(7n + 8)::before {
  animation: 0.8s linear 0.8s normal none infinite running load;
  background: $gradient-10 none repeat scroll 0 0;
}
#loader .lading {
  background-position: 50% 50%;
  background-repeat: no-repeat;
  bottom: -40px;
  height: 20px;
  left: 0;
  position: absolute;
  right: 0;
  width: 180px;
}
@keyframes load {
  100% {
    opacity: 0;
    transform: scale(1);
  }
}
@keyframes load {
  100% {
    opacity: 0;
    transform: scale(1);
  }
}

// Animation

/*Vertical Flip Animation*/

@include keyframes(build) {
  0% {
    opacity: 0;
    transform: rotateX(180deg);
  }
  5% {
    opacity: 1;
    transform: translateY(0px);
  }
  10% {
    opacity: 1;
    transform: translateY(0px);
  }
  25% {
    opacity: 1;
    transform: translateY(0px);
  }
  80% {
    opacity: 1;
  }
  100% {
    opacity: 1;
  }
}
@include keyframes(create) {
  0% {
    opacity: 0;
    transform: rotateX(180deg);
  }
  5% {
    opacity: 1;
    transform: translateY(0px);
  }
  10% {
    opacity: 1;
    transform: translateY(0px);
  }
  25% {
    opacity: 1;
    transform: translateY(0px);
  }
  80% {
    opacity: 1;
  }
  100% {
    opacity: 1;
  }
}
@include keyframes(promote) {
  0% {
    opacity: 0;
    transform: rotateX(180deg);
  }
  5% {
    opacity: 1;
    transform: translateY(0px);
  }
  10% {
    opacity: 1;
    transform: translateY(0px);
  }
  25% {
    opacity: 1;
    transform: translateY(0px);
  }
  80% {
    opacity: 1;
  }
  100% {
    opacity: 1;
  }
}

@keyframes gradient {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}

.build-menu {
  animation: build 10s forwards;
  color: #0eaf7d;
  opacity: 0;
  overflow: hidden;
  position: absolute;
}
.create-menu {
  animation: create 10s forwards;
  color: $gradient-2;
  opacity: 0;
  overflow: hidden;
  position: absolute;
}
.promote-menu {
  animation: promote 10s forwards;
  color: $gradient-7;
  opacity: 0;
  overflow: hidden;
  position: absolute;
}

@include keyframes(shadow-pulse) {
  0% {
    box-shadow: 0 0 0 0px rgba(255, 255, 0, 0.2);
  }
  100% {
    box-shadow: 0 0 0 35px rgba(255, 255, 0, 0);
  }
}

@include keyframes(spin) {
  100% {
    transform: rotate(360deg);
  }
}
@include keyframes(bounce) {
  25% {
    transform: scale(0.9);
  }
  50% {
    transform: scale(1.2);
  }
  75% {
    transform: scale(0.9);
  }
  100% {
    transform: scale(1);
  }
}

@include keyframes(scale) {
  50% {
    transform: scale(0.5);
  }
}

.fadeAll {
  @include fadeInUp($delay: 0.1s, $function: ease);
}

.fadeInUp {
  @include fadeInUp($delay: 0.3s);
}

.hidden-animate {
  visibility: hidden;
}

// General

body {
  line-height: 24px;
}

h1 {
  color: $h-black;
  @include font-size(34px, 16px);
  font-weight: bold;
  line-height: 70px;
  @include media-breakpoint-up(md) {
    @include font-size(48px, 16px);
  }
  @include media-breakpoint-up(lg) {
    line-height: 70px;
    @include font-size(68px, 16px);
  }
}

h2,
h3 {
  color: $p-black;
}

h2 {
  @include font-size(26px, 16px);
  line-height: 35px;
}

h3 {
  @include font-size(16px, 16px);
}

p,
a {
  color: $p-black;
  @include font-size(16px, 16px);
  @include media-breakpoint-up(md) {
    @include font-size(15px, 16px);
  }
}

a {
  &:hover {
    color: $primary;
    text-decoration: none;
    transition: 0.3s;
  }
  &.see-more {
    @include font-size(15px, 16px);
    font-weight: bold;
    &.go-left {
      margin-right: auto;
    }
    &:hover {
      i {
        transform: translateX(70px);
        transition: 0.3s;
        &.left {
          transform: translateX(-20px);
        }
      }
    }
    i {
      transition: 0.3s;
      transform: translateX(20px);
      &.left {
        padding-left: 10px;
        padding-right: 4px;
        transform: translateX(-10px);
      }
    }
  }
}

a.btn {
  background-color: $primary;
  border-radius: 1px;
  color: $white;
  cursor: pointer;
  display: flex;
  font-size: 15px;
  font-weight: bold;
  justify-content: center;
  padding: 8px 8px 8px;
  width: 170px;
  border: 2px solid $primary;
  &:hover {
    box-shadow: 0px 4px 10px 0 rgba($grey, 0.5);
  }
  &.btn-second {
    color: $primary;
    background-color: $white;
    &:hover {
      background-color: $primary;
      color: $white;
    }
  }
}

.grey-line {
  border: 2px solid $light-grey;
  margin-bottom: 5px;
}

.box-gray {
  background-color: $light-grey;
}

.line-gradient {
  width: 100%;
  height: 1px;
  display: block;
  /* SVG fallback for IE 9 (could be data URI, or could use filter) */
  background: url(../../img/large.svg);
  @include x-multiple-colored-gradient("left", $line-gradient);
  &.nav-gradient {
    position: absolute;
    top: 0px;
    display: inline;
    margin-left: -16px;
    height: 2px;
  }
}

.container {
  @include media-breakpoint-up(xxl) {
    max-width: 1350px;
  }
}

