// =========Hamburger icon=========

.burger {
  margin: 0px;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 1s ease;
  border: none;
  background: transparent;
  &:focus {
    outline: none;
  }
  .cta {
    height: 50px;
    width: 50px;
    cursor: pointer;
    border: none;
  }
}
.toggle-btn {
  height: 2px;
  width: 25px;
  background-color: $h-black;
  position: relative;
  top: 50%;
  left: 0;
  margin: auto;
  transition: all 0.3s ease-in-out;
}

.toggle-btn:before {
  content: "";
  height: 2px;
  width: 25px;
  box-shadow: 0 -10px 0 0 $h-black;
  position: absolute;
  top: 0;
  left: 0;
  transition: all 0.3s ease-in-out;
}
.toggle-btn:after {
  content: "";
  height: 2px;
  width: 25px;
  box-shadow: 0 10px 0 0 $h-black;
  position: absolute;
  top: 0;
  left: 0;
  transition: all 0.3s ease-in-out;
}

.active .toggle-btn {
  background-color: transparent;
  transition: all 0.2s ease-in-out;
}
.active .toggle-btn:before {
  top: 0;
  transition: all 0.3s ease-in-out;
}
.active .toggle-btn:after {
  top: 0;
  transition: all 0.3s ease-in-out;
}
.active .type11 {
  transform: rotate(90deg);
  transition: all 0.4s ease-in-out;
}
.active .type11:before {
  transform: translateY(0) rotate(40deg);
}
.active .type11:after {
  transform: translateY(0) rotate(-40deg);
}

// =========== Header ==========

#wrapper-navbar {
  background: transparent;
  width: 100%;
  // -------  navbar homepage  -------
  &.navbar-home {
    background: transparent;
    #main-logo {
      .cls-1 {
        fill: $white;
      }
    }
    .navbar.bg-primary {
      border-bottom: 2px solid transparent;
      background: transparent !important;
      &.navwhite {
        background: $white !important;
        border-bottom: 1px solid #f4f4f4;
        .container-fluid {
          #main-menu {
            li.menu-item {
              .nav-link {
                color: $grey;
                &:hover {
                  color: $dark-blue;
                }
              }
            }
          }
        }
        .dropdown:hover .dropdown-menu {
          li {
            @include media-breakpoint-up(md) {
              -webkit-box-shadow: 0px 2px 3px 0px rgba(84, 114, 198, 0.4);
              -moz-box-shadow: 0px 2px 3px 0px rgba(84, 114, 198, 0.4);
              box-shadow: 0px 2px 0px 0px rgba(84, 114, 198, 0.4);
              background-color: $light-grey;
              &:nth-child(2) {
                &::before {
                  border-top: 15px solid $white;
                }
              }
            }
          }
        }
      }
      .container-fluid {
        #main-menu {
          li.menu-item {
            .nav-link {
              @include media-breakpoint-up(md) {
                color: $white;
              }
            }
          }
        }
      }
    }
    .line-gradient {
      z-index: 99;
      position: absolute;
    }
    .dropdown:hover .dropdown-menu {
      li {
        @include media-breakpoint-up(md) {
          background-color: transparent;
          box-shadow: none;
          &:nth-child(2) {
            &::before {
              border-top: none;
            }
          }
        }
      }
    }
  }
  // --------- dropdown ---------
  #main-logo {
    height: 62px;
    width: 150px;
    transition: 0.8s;
    .cls-1 {
      fill: #1a1a1a;
    }
  }
  .navbar.bg-primary {
    background: transparent;
    width: 100%;
    line-height: 60px;
    z-index: 100;
    padding-bottom: 0px;
    transition: 0.5s;
    border-bottom: 1px solid $grey;
    .container-fluid {
      #main-menu {
        li.menu-item {
          padding-right: 28px;
          &:last-child {
            padding-right: 0px;
          }
          &:nth-child(2) {
            @include media-breakpoint-up(md) {
              padding-left: 28px;
            }
          }
          &:first-child {
            padding-right: 0px;
          }
          &.active {
            .nav-link {
              font-weight: 600;
              color: $dark-blue;
            }
          }
          .nav-link {
            color: $grey;
            font-weight: 500;
            transition: 0.3s;
            &:hover {
              color: $dark-blue;
            }
          }
        }
      }
      a {
        color: $grey;
      }
    }
  }
  .navbar.navwhite {
    background: $white !important;
    transition: 0.5s;
    padding-top: 0px;
    padding-bottom: 0px;
    #main-logo {
      transition: 0.8s;
      width: 120px;
      height: 50px;
    }
  }
}

// ========Footer==========

#wrapper-footer {
  background-color: $dark-blue;
  padding-bottom: 0px;
  p {
    color: $grey;
    font-size: 13px;
    margin-bottom: 0px;
  }
  a {
    font-size: 13px;
    color: $white;
    &:hover {
      color: $grey;
    }
  }
  .footer-info {
    min-height: 500px;
    .social {
      padding-bottom: 30px;
      @include media-breakpoint-up(md) {
        padding-bottom: 58px;
      }
      ul {
        padding: 0px;
        li {
          display: inline;
          padding-right: 4px;
        }
        .social-svg {
          width: 26px;
          .cls-1 {
            transition: 0.3s;
          }
          &:hover {
            .cls-1 {
              fill: $primary;
              background: $white;
              transition: 0.3s;
            }
          }
        }
      }
