    width: 50px;
    border-radius: 50px;
    top: 50%;
    @include hover-focus {
      opacity: 0.5;
    }
    @include hover {
      opacity: 1;
    }
    @include media-breakpoint-down(sm) {
      height: 40px;
      width: 40px;
    }
  }
  .carousel-control-next {
    right: 2%;
  }
  .carousel-control-prev {
    left: 2%;
  }
}
.products {
  padding-bottom: 100px;
  h5 {
    font-weight: bold;
  }
  .row.design {
    padding-top: 60px;
    padding-bottom: 60px;
    @include media-breakpoint-up(md) {
      padding-top: 120px;
      padding-bottom: 100px;
    }
    p {
      font-size: 14px;
    }
  }

  .row.mobile {
    .mobile-background-2 {
      background-color: $light-grey;
      img {
        @include center-block;
      }
    }
    .mobile-background-1 {
      background-color: #f0f0f0;
      img {
        @include center-block;
      }
    }
  }
}
.final-box-work {
  h5 {
    font-weight: bold;
  }
  p {
    font-size: 14px;
  }
  .result {
    padding-bottom: 50px;
    .inner-result {
      @include media-breakpoint-up(md) {
        width: 80%;
      }
      h5 {
        padding-bottom: 17px;
      }
    }
  }
  .quote {
    display: none;
    padding-bottom: 50px;
    @include media-breakpoint-up(md) {
      display: block;
    }
    .inner-quote {
      width: 70%;
      padding-top: 44px;
      p {
        line-height: 40px;
        font-weight: 300;
        letter-spacing: 1px;
      }
    }
    p {
      font-size: 30px;
    }
  }
  .see-more {
    display: block;
    padding-top: 10px;
    margin-bottom: 50px;
    @include media-breakpoint-up(md) {
      margin-bottom: 105px;
    }
    &:hover {
      color: $p-black;
      i {
        color: $primary;
        transition: 0.4s;
      }
    }
  }
}

// ================== Insight ===========
.grid-insight {
  padding-bottom: 35px;
}
.insight-info {
  display: flex;
  justify-content: space-between;
  padding-top: 23px;
  .insight-date {
    @include font-size(14px, 16px);
    color: $grey;
    padding-bottom: 13px;
    margin-bottom: 0px;
  }
  .insight-cat {
    @include font-size(14px, 16px);
    text-transform: uppercase;
    font-weight: bold;
    padding-bottom: 13px;
    margin-bottom: 0px;
  }
}
.insight-grid {
  padding-bottom: 15px;
  padding-top: 15px;
  overflow: hidden;
  > a {
    overflow: hidden;
  }
  &:hover {
    img {
      -webkit-box-shadow: 0px 0px 9px 0px rgba(0, 0, 0, 0.36);
      -moz-box-shadow: 0px 0px 9px 0px rgba(0, 0, 0, 0.36);
      box-shadow: 0px 0px 9px 0px rgba(0, 0, 0, 0.36);
    }
    .insight-title {
      h4 {
        text-decoration: underline;
      }
    }
  }
  .grey-line {
    border-width: 1px;
    margin-bottom: 13px;
  }
  .insight-title {
    padding-bottom: 55px;
    h4 {
      @include font-size(15px, 16px);
      font-weight: bold;
      margin-bottom: 0px;
      padding-bottom: 13px;
      color: $primary;
    }
  }
  img {
    transition: 0.4s ease-out;
  }
}
.insight-pagination {
  display: flex;
  justify-content: center;
  margin-top: 15px;
  margin-bottom: 120px;
  .my-pagination {
    .page-item {
      margin-right: 15px;
      border-radius: 100%;
      width: 10px;
      height: 10px;
      border: none;
      border-radius: 100%;
      border: 1.1px solid $primary;
      background-color: transparent;
      transition: all 0.25s ease;
      &:hover,
      &.active {
        background-color: $primary;
      }
      a {
        display: block;
        width: 100%;
        height: 100%;
        background-color: transparent;
        transition: all 0.25s ease;
      }
    }
  }
}

// ============= Inner Insight ==========

.insight-hero {
  background-repeat: no-repeat;
  height: 270px;
  position: relative;
  text-align: center;
  padding: 30px;
  margin-top: -30px;
  background-size: cover;
  @include media-breakpoint-up(md) {
    height: 370px;
  }
  @include media-breakpoint-up(xl) {
    height: 430px;
  }
  .social-share-icon {
    position: absolute;
    bottom: 3%;
    right: 3%;
    @include media-breakpoint-down(sm) {
      display: none;
    }
  }
  .social-share-icon a.a {
    z-index: 123;
  }
  .social-share-icon a {
    text-decoration: none;
    color: $primary;
    height: 45px;
    width: 45px;
    border-radius: 100px;
    display: inline-block;
    background-color: rgba($light-grey, 1);
    line-height: 45px;
    text-align: center;
    box-shadow: 0 2px 3px 0 rgba(0, 0, 0, 0.2);
  }
  .social-share-icon a:hover {
    background-color: $primary;
    color: $light-grey;
  }
  .social-share-icon a i {
    line-height: inherit;
  }
  .social-share-icon a.a1 {
    transform: translateX(30px);
    transition: all ease-in-out 200ms;
    opacity: 0;
  }
  .social-share-icon a.a2 {
    transform: translateX(20px);
    transition: all ease-in-out 300ms;
    opacity: 0;
  }
  .social-share-icon a.a3 {
    transform: translateX(10px);
    transition: all ease-in-out 400ms;
    opacity: 0;
  }
  .social-share-icon:hover a.a1 {
    transform: translateX(0);
    transition: all ease-in-out 600ms;
    opacity: 1;
  }
  .social-share-icon:hover a.a2 {
    transform: translateX(0);
    transition: all ease-in-out 500ms;
    opacity: 1;
  }
  .social-share-icon:hover a.a3 {
    transform: translateX(0);
    transition: all ease-in-out 400ms;
    opacity: 1;
  }
  .inner-category-hero {
    h4 {
      font-size: 15px;
      font-weight: bold;
      color: $white !important;
      letter-spacing: 1px;
    }
  }
  .insight-title {
    position: relative;
    top: 50%;
    transform: perspective(1px) translateY(-50%);
    @include media-breakpoint-down(md) {
      // This to support old IOS 5/6 that don't support inline background image
      background-color: rgba(0, 0, 0, 0.6);
      padding: 10px;
    }
    h1 {
      font-size: 28px;
      font-weight: 400;
      color: $white;
      line-height: 35px;
      @include media-breakpoint-up(sm) {
        font-size: 32px;
      }
      @include media-breakpoint-up(md) {
        font-size: 36px;
      }
    }
  }
}
.insight-content {
  padding-bottom: 74px;
  padding-top: 74px;
  .insight-info {
    .date {
      font-weight: bold;
      font-size: 15px;
    }
    .category {
      text-transform: uppercase;
      font-size: 13px;
      color: $primary;
      font-weight: bold;
    }
  }
  .entry-content {
    h1 {
      line-height: 50px;
    }
  }
  p {
    font-size: 16px;
  }
  .entry-footer {
    .see-more.go-left {
      color: $grey;
      padding-top: 44px;
      display: block;
      &:hover {
        i.left {
          color: $primary;
        }
      }
      i.left {
        padding-left: 0px;
      }
    }
    .grey-box {
      background-color: $light-grey;
      padding: 34px 34px;
      @include media-breakpoint-up(md) {
        padding-left: 100px;
        padding-right: 100px;
      }
      h3 {
        font-size: 21px;
        padding-bottom: 14px;
      }
      p {
        a {
          font-size: 16px;
          color: $primary;
          &:hover {
            color: $p-black;
          }
        }
      }
    }
  }
}

// ================== Services ==================

.services {
  margin-top: 60px;
  margin-bottom: 60px;
  @include media-breakpoint-up(md) {
    margin-bottom: 73px;
  }
}

.services-wrapper {
  padding-left: 0px;
  padding-right: 0px;
  position: relative;
