// jumbotrone section
.jumbotrone {
  background-position: center;
  background-repeat: no-repeat;
  margin-bottom: 80px;
  position: relative;
  min-height: 600px;
  display: flex;
  align-items: center;
  @include media-breakpoint-up(xxl) {
    background-size: cover;
  }
  h1 {
    color: $white;
    text-transform: uppercase;
    padding-top: 0px;
    text-align: center;
    margin-left: -60px;
    font-weight: 900;
    @include media-breakpoint-down(md) {
      margin-left: 0px;
      font-size: 3rem;
    }
    @include media-breakpoint-up(lg) {
      padding-top: 10px;
      margin-left: 0px;
      text-align: left;
      padding-bottom: 15px;
    }
  }
  svg {
    position: relative;
    top: 50%;
    transform: translateY(-50%);
    padding-right: 30px;
    height: 50px;
    @include media-breakpoint-down(md) {
      padding-right: 3px;
      height: 80px;
      display: none;
    }
    @include media-breakpoint-up(lg) {
      height: 97px;
    }
    .cls-1 {
      fill: $white;
    }
    .cls-2 {
      fill: $white;
    }
    .cls-3 {
      fill: $white;
    }
  }
  .service-overlay {
    position: absolute;
    top: 0px;
    left: 0px;
    width: 100%;
    height: 100%;
    z-index: 0;
    animation: gradient 15s ease infinite;
    opacity: 0.7;
  }
  h2 {
    color: $white;
    font-size: 18px;
    text-align: center;
    text-transform: uppercase;
    font-weight: 300;
    @include media-breakpoint-up(lg) {
      text-align: left;
      font-size: 21px;
    }
  }
  p {
    color: $white;
    text-align: center;
    margin: auto;
    @include media-breakpoint-up(lg) {
      font-size: 16px;
      text-align: left;
      margin: 0px;
      width: 80%;
    }
  }
  .btn {
    background-color: transparent;
    border-color: $white;
    margin-top: 30px;
    @include media-breakpoint-down(md) {
      margin-left: auto;
      margin-right: auto;
    }
    &:hover {
      box-shadow: none;
      background-color: $white;
    }
    &.btn-build {
      &:hover {
        color: #0e9f9c;
      }
    }
    &.btn-create {
      &:hover {
        color: #d8351b;
      }
    }
    &.btn-promote {
      &:hover {
        color: #73244b;
      }
    }
  }
}

