        font-weight: 200;
      }
    }
    .image-service {
      margin-top: 68px;
      max-width: 100%;
      margin-left: auto;
      margin-right: auto;
      height: auto;
      @include media-breakpoint-down(sm) {
        // background: rgba(0, 202, 255, .2)!important;  /* fallback for old browsers */
        // background: -webkit-linear-gradient(to bottom, rgba(0, 202, 255, .2), rgba(0, 240, 167, .2), rgba(0, 255, 131, .2))!important;  /* Chrome 10-25, Safari 5.1-6 */
        // background: linear-gradient(to bottom, rgba(0, 202, 255, .2), rgba(0, 240, 167, .2), rgba(0, 255, 131, .2))!important; /* W3C, IE 10+/ Edge, Firefox 16+, Chrome 26+, Opera 12+, Safari 7+ */
        background: $white !important;
      }
      @include media-breakpoint-up(lg) {
        height: 587px;
        width: 1206px;
      }
      .image-service-element {
        border-color: $white;
        border-width: 1px;
        border-bottom-style: solid;
        transition: 0.3s;
        &:hover {
          @include media-breakpoint-up(lg) {
            background-color: rgba(26, 28, 34, 0.6);
            transition: 0.3s;
            .element-visible {
              -moz-transform: translateY(-270%);
              -webkit-transform: translateY(-270%);
              -ms-transform: translateY(-270%);
              transform: translateY(-270%);
              transition: 0.3s;
            }
            .element-hidden {
              transition: 0.1s;
              z-index: 0;
              @include fadeInUp($delay: 0.2s);
            }
          }
        }
        @include media-breakpoint-up(md) {
          border-right-style: solid;
        }
        p,
        h3 {
          color: $white;
          padding-right: 10px;
          @include media-breakpoint-down(sm) {
            color: $p-black;
          }
        }
        .element-hidden,
        .element-visible {
          width: 100%;
          padding-left: 10px;
          padding-right: 10px;
        }
        .element-visible {
          transition: 0.3s;
          text-align: center;
          @include media-breakpoint-up(lg) {
            text-align: left;
            position: absolute;
            bottom: 46px;
          }
          .nth-element {
            font-size: 34px;
            padding-top: 25px;
            font-weight: bold;
            @include media-breakpoint-up(lg) {
              font-size: 84px;
              padding-bottom: 10px;
            }
          }
          h3 {
            font-size: 15px;
            font-weight: bold;
          }
        }
        .element-hidden {
          padding-bottom: 26px;
          @include media-breakpoint-up(lg) {
            position: absolute;
            bottom: 0px;
            transition: 0.4s;
            z-index: -100;
          }
          p {
            font-size: 14px;
            font-weight: 300;
            @include media-breakpoint-up(lg) {
              font-size: 15px;
              margin-right: 5px;
            }
          }
        }
      }
    }
  }
}

